/* ------------------------------- Questions ------------------------------- */
const timeframe = {
  critical: l('Within 30 days', 'Binnen 30 dagen'), high: l('Within 90 days', 'Binnen 90 dagen'),
  medium: l('Within 6 months', 'Binnen 6 maanden'), low: l('Within 12 months', 'Binnen 12 maanden'),
};

/** Maturity-scale question (0–4) with "Not sure" enabled. */
function m(code: string, category: string, title: L, description: L | null, extra: Partial<Question> = {}): Question {
  return { code, category, type: 'maturity', title, ...(description ? { description } : {}), allow_unsure: true, weight: 1, required: true, risk: 'medium', ...extra };
}
const crit = (finding: L, max = 1) => ({ max_score: max, unsure: true, finding });

