/* -------------------------- Recommendation rules -------------------------- */
function rule(code: string, priority: Rule['priority'], category: string, service: string | null, title: L, description: L, impact: L, remediation: L,
  conditions: Rule['trigger']['conditions'], mode: 'any' | 'all' = 'any', templates: string[] = []): Rule {
  return { code, priority, category, service, title, description, impact, remediation, timeframe: timeframe[priority], templates, trigger: { mode, conditions } };
}

